#include <bits/stdc++.h>
using namespace std;

void Add(int a[], int m, int b[], int n) {
    for (int i = 0; i < n; i++) a[m + i] = b[i];
}

int main() {
    int m, n;
    cin >> m >> n;
    int *a = new int[m + n];
    int *b = new int[n];
    for (int i = 0; i < m; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];
    int m1, n1;
    cin >> m1 >> n1;
    Add(a, m1, b, n1);
    for (int i = 0; i < m1 + n1; i++) {
        if (i) cout << ", ";
        cout << a[i];
    }
    cout << endl;
    return 0;
}
